  @Override
  public StaticSlot<JSType> getSlot(String name) {
    return getVar(name);
  }

  @Override
  public StaticSlot<JSType> getOwnSlot(String name) {
    return vars.get(name);
  }

  /**
   * Returns the variable, may be null
   */
  public Var getVar(String name) {
    Var var = vars.get(name);
    if (var != null) {
      return var;
