                JSDocInfo info) {
      this.name = name;
      this.nameNode = nameNode;
      this.type = type;
      this.scope = scope;
      this.index = index;
      this.input = input;
      this.isDefine = isDefine;
      this.info = info;
      this.typeInferred = inferred;
    }

